        if identity in seen:fail("Pinned source file roles alias",name)
        seen.add(identity)
        if before.st_size!=expected["size"]:fail("Pinned f152 source byte count differs",name)
        raw=path.read_bytes();after=path.stat()
        if (before.st_ino,before.st_size,before.st_mtime_ns)!=(after.st_ino,after.st_size,after.st_mtime_ns):fail("Source changed while reading",name,"rr_f152_input_changed")
